package com.eventfinder.controller;
import com.eventfinder.dto.*;import com.eventfinder.service.AuthService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService service;public AuthController(AuthService s){service=s;}@PostMapping("/register") public TokenResponse register(@Valid @RequestBody RegisterRequest r){return service.register(r);}@PostMapping("/login") public TokenResponse login(@Valid @RequestBody AuthRequest r){return service.login(r);}}